#!/usr/bin/env node
/**
 * Regenerate `scripts/apply-all-migrations.sql` from `supabase/migrations/*.sql`.
 *
 * The Supabase SQL Editor is the apply path for this project (no direct database
 * password is stored in the repo), so the numbered migrations are concatenated
 * in order into one paste-able, re-runnable script. Keeping this generated
 * rather than hand-maintained means a new migration can never be silently left
 * out of the bundle.
 *
 * Usage: node scripts/build-migration-bundle.mjs
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = resolve(repoRoot, "supabase/migrations");
const outputPath = resolve(repoRoot, "scripts/apply-all-migrations.sql");

const files = readdirSync(migrationsDir)
  .filter((name) => name.endsWith(".sql"))
  .sort();

if (files.length === 0) {
  console.error("No migrations found in supabase/migrations.");
  process.exit(1);
}

const first = files[0].slice(0, 4);
const last = files[files.length - 1].slice(0, 4);

const header = [
  "-- Dizkarte — consolidated schema for the Supabase SQL Editor.",
  `-- Generated from supabase/migrations/${first}..${last} in order.`,
  "-- Generated by scripts/build-migration-bundle.mjs — do not edit by hand.",
  "-- Paste this whole file into your project's SQL Editor and run it once.",
  "-- Safe to re-run: every statement uses create-if-not-exists / or-replace /",
  "-- drop-if-exists patterns.",
  "",
  "",
].join("\n");

const sections = files.map((name) => {
  const body = readFileSync(resolve(migrationsDir, name), "utf8").trimEnd();
  return [
    "-- ===================================================================",
    `-- ${name}`,
    "-- ===================================================================",
    "",
    body,
    "",
    "",
  ].join("\n");
});

writeFileSync(outputPath, header + sections.join("\n"), "utf8");
console.log(`Wrote ${outputPath} from ${files.length} migrations (${first}..${last}).`);
